{
  "name": "Scientifica 运动控制线程",
  "name_en": "Scientifica Motion Control Thread",
  "manufacturer": "",
  "description": "这是一个非物理的软件控制组件，用于主 Scientifica 设备类的后台线程中监测位置、发起移动、跟踪移动状态、处理停止与取消请求，并通过回调通知位置或物镜状态变化，适合用于 Scientifica 位移设备的运动协调与状态轮询。",
  "description_en": "This is a non-physical software control component used as a background thread for the main Scientifica device class. It monitors position, initiates moves, tracks move status, handles stop and cancel requests, and reports position or objective changes via callbacks for coordinating and polling Scientifica motion devices.",
  "actions": [
    {
      "action_name": "auto-set_pos_callback",
      "description": "设置位置变化时触发的回调函数",
      "description_en": "Set the callback invoked when the position changes."
    },
    {
      "action_name": "auto-set_obj_callback",
      "description": "设置物镜变化时触发的回调函数",
      "description_en": "Set the callback invoked when the objective changes."
    },
    {
      "action_name": "auto-set_default_speed",
      "description": "设置默认移动速度",
      "description_en": "Set the default move speed."
    },
    {
      "action_name": "auto-stop",
      "description": "立即停止当前设备运动",
      "description_en": "Immediately stop the current device motion."
    },
    {
      "action_name": "auto-move",
      "description": "请求设备以指定速度移动到目标位置",
      "description_en": "Request the device to move to a target position at a specified speed."
    },
    {
      "action_name": "auto-quit",
      "description": "退出控制线程",
      "description_en": "Quit the control thread."
    },
    {
      "action_name": "auto-cancel_move",
      "description": "取消先前提交的移动请求",
      "description_en": "Cancel a previously submitted move request."
    },
    {
      "action_name": "auto-run",
      "description": "运行控制循环并检查位置与移动状态",
      "description_en": "Run the control loop and check position and move status."
    },
    {
      "action_name": "auto-send_move_command",
      "description": "按顺序发送移动相关命令",
      "description_en": "Send the move-related command sequence."
    },
    {
      "action_name": "auto-check_position",
      "description": "检查当前位置与移动状态，并在需要时更新回调或重试移动",
      "description_en": "Check the current position and move status, and update callbacks or retry the move if needed."
    },
    {
      "action_name": "auto-check_objective",
      "description": "检查当前物镜状态",
      "description_en": "Check the current objective status."
    }
  ],
  "tag_hints": [
    "motion control thread",
    "position polling",
    "asynchronous move requests",
    "move status tracking",
    "callback notifications",
    "Scientifica integration",
    "objective state monitoring"
  ]
}

